    'deploy.storage_objects.some' => 'todavía tiene archivos. Copia los que necesites y luego vacía y elimina el bucket en la consola de S3 cuando ya no lo necesites.',
    'deploy.storage_objects.none' => 'está vacío. Elimínalo en la consola de S3 cuando ya no lo necesites.',
    'deploy.storage_objects.unknown' => 'no se pudieron listar sus archivos. Revísalo en la consola de S3, copia los archivos que necesites y luego vacíalo y elimínalo cuando ya no lo necesites.',
    'deploy.table_kind.cache' => 'tabla de caché',
    'deploy.table_kind.failed-jobs' => 'tabla de trabajos fallidos',
    'deploy.table_kept_unknown' => 'La tabla {table} ya no está en arco.php. Arco la conservó en AWS con sus elementos; no se pudo leer cuántos son. Exporta los elementos que necesites y elimínala en la consola de DynamoDB cuando ya no la necesites.',
    'remove.table_kept_unknown' => 'La tabla {table} se conservó en AWS con sus elementos; no se pudo leer cuántos son. Exporta los elementos que necesites y elimínala en la consola de DynamoDB cuando ya no la necesites.',
    'deploy.lookup_denied' => 'Arco no pudo comprobar si {name} ya existe: el perfil no tiene {permission}. No se cambió nada. Permite {permission} en el perfil y vuelve a desplegar.',
    'deploy.storage_kept' => 'El bucket {bucket} ya no está en arco.php. Arco lo conservó en AWS: {objects}',
